from pathlib import Path
import sys

p = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('psico-engine.js')
s = p.read_text(encoding='utf-8')
marker = "\n/* PLACURSO_PHASE3B_EXPERIENCE */\n"
if marker in s:
    raise SystemExit('Fase 3B já aplicada.')
if '.pch-games-hub' not in s:
    raise SystemExit('ERRO: hub de jogos não encontrado; a Fase 3B deve ser aplicada depois da Fase 3A.')

script = r'''\n/* PLACURSO_PHASE3B_EXPERIENCE */\n(function(){\n  function boot(){\n    var hub=document.querySelector('.pch-games-hub');\n    if(!hub || hub.dataset.phase3b==='1') return;\n    hub.dataset.phase3b='1';\n    var KEY='placurso_phase3b_experience_v1';\n    var EMPTY={xp:0,plays:0,bestScore:0,lastPlayedAt:null,skills:{memory:0,focus:0,decision:0,strategy:0,finance:0},masters:{memoria:0,reflexo:0,dinheiro:0,negocio:0},daily:{date:null,completed:false}};\n    function fresh(){return JSON.parse(JSON.stringify(EMPTY));}\n    function load(){var out=fresh();try{var raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){out.xp=Math.max(0,Number(raw.xp)||0);out.plays=Math.max(0,Number(raw.plays)||0);out.bestScore=Math.max(0,Number(raw.bestScore)||0);out.lastPlayedAt=typeof raw.lastPlayedAt==='string'?raw.lastPlayedAt:null;Object.keys(out.skills).forEach(function(k){out.skills[k]=Math.max(0,Math.min(100,Number(raw.skills&&raw.skills[k])||0));});Object.keys(out.masters).forEach(function(k){out.masters[k]=Math.max(0,Math.min(5,Number(raw.masters&&raw.masters[k])||0));});if(raw.daily&&typeof raw.daily==='object'){out.daily.date=typeof raw.daily.date==='string'?raw.daily.date:null;out.daily.completed=raw.daily.completed===true;}}}catch(e){}return out;}\n    var state=load();\n    function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}\n    function dateKey(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}\n    var today=dateKey();if(state.daily.date!==today){state.daily={date:today,completed:false};save();}\n    var games={memoria:{skill:'memory',label:'Memória em cadeia',icon:'🧠',colorClass:'memory'},reflexo:{skill:'focus',label:'Reflexo rápido',icon:'⚡',colorClass:'focus'},dinheiro:{skill:'finance',label:'Decisão financeira',icon:'💰',colorClass:'finance'},negocio:{skill:'strategy',label:'Mini negócio',icon:'♟',colorClass:'strategy'}};\n    var css=document.createElement('style');css.textContent=`\n      .p3b-experience{margin:18px 0 22px;padding:16px;border:1px solid #D9C8A7;border-radius:22px;background:linear-gradient(180deg,#fffdf8,#f7f2e9);box-shadow:0 12px 30px rgba(32,42,36,.07)}\n      .p3b-top{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(240px,.75fr);gap:12px}.p3b-identity{padding:17px;border-radius:17px;background:#202A24;color:#F7EBD1}.p3b-eyebrow{font-size:9px;font-weight:900;letter-spacing:1.4px;color:#D8C59F}.p3b-title{margin:7px 0 5px;font-size:clamp(22px,5vw,31px);line-height:1.08}.p3b-copy{margin:0;color:#E6DDCB;font-size:12px;line-height:1.55}.p3b-next{margin-top:13px;display:flex;align-items:center;justify-content:space-between;gap:10px}.p3b-primary{min-height:44px;padding:0 14px;border:0;border-radius:12px;background:#A43D2F;color:#fff;font-weight:900;cursor:pointer}.p3b-primary:focus-visible,.p3b-skill:focus-visible,.p3b-mastery:focus-visible{outline:3px solid #D8C59F;outline-offset:2px}\n      .p3b-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.p3b-stat{padding:11px;border:1px solid #E0D5C2;border-radius:13px;background:#fff}.p3b-stat strong{display:block;font-size:18px}.p3b-stat span{font-size:9px;color:#756D60;font-weight:800;text-transform:uppercase;letter-spacing:.4px}\n      .p3b-section-title{display:flex;justify-content:space-between;gap:10px;align-items:end;margin:16px 0 8px}.p3b-section-title h3{margin:0;font-size:16px}.p3b-section-title p{margin:0;color:#756D60;font-size:10px}.p3b-skills{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.p3b-skill{padding:10px;border:1px solid #E0D5C2;border-radius:13px;background:#fff;text-align:left;cursor:pointer}.p3b-skill-top{display:flex;justify-content:space-between;gap:5px;font-size:10px;font-weight:900}.p3b-meter{height:6px;margin-top:8px;background:#E8E0D2;border-radius:99px;overflow:hidden}.p3b-meter i{display:block;height:100%;width:0;background:#A43D2F;border-radius:99px;transition:width .35s ease}.p3b-skill small{display:block;margin-top:5px;color:#756D60;font-size:9px}\n      .p3b-mastery{padding:11px;border:1px solid #E0D5C2;border-radius:14px;background:#fff;text-align:left;cursor:pointer}.p3b-mastery-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.p3b-mastery strong{display:block;font-size:11px}.p3b-mastery small{display:block;margin-top:4px;color:#756D60;font-size:9px}.p3b-dots{display:flex;gap:4px;margin-top:8px}.p3b-dots i{width:8px;height:8px;border-radius:50%;background:#E2D8C7}.p3b-dots i.on{background:#A43D2F}\n      .p3b-daily{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px;border:1px solid #D9C8A7;border-radius:14px;background:#FBF6EA}.p3b-daily-copy strong{display:block;font-size:12px}.p3b-daily-copy span{display:block;margin-top:3px;color:#756D60;font-size:10px;line-height:1.4}.p3b-daily.done{background:#EEF3EC}.p3b-badge{padding:5px 7px;border-radius:999px;background:#EEE6D6;color:#4D4438;font-size:8px;font-weight:900;white-space:nowrap}\n      .p3b-return{margin-top:10px;padding:10px 12px;border-radius:12px;background:#202A24;color:#EDE5D7;font-size:10px;line-height:1.45}.p3b-return strong{color:#fff}\n      @media(max-width:760px){.p3b-top{grid-template-columns:1fr}.p3b-skills{grid-template-columns:repeat(2,minmax(0,1fr))}.p3b-mastery-grid{grid-template-columns:1fr 1fr}}\n      @media(max-width:390px){.p3b-stats{grid-template-columns:1fr 1fr}.p3b-stats .p3b-stat:last-child{grid-column:1/-1}.p3b-mastery-grid{grid-template-columns:1fr}.p3b-next{align-items:stretch;flex-direction:column}.p3b-primary{width:100%}}\n      @media(prefers-reduced-motion:reduce){.p3b-meter i{transition:none}}\n    `;document.head.appendChild(css);\n\n    var section=document.createElement('section');section.className='p3b-experience';section.setAttribute('aria-label','Experiência ANNAN Fase 3B');section.innerHTML=`\n      <div class="p3b-top"><div class="p3b-identity"><div class="p3b-eyebrow">ANNAN · FASE 3B</div><div class="p3b-title">A tua evolução fica visível.</div><p class="p3b-copy">Joga, recebe feedback e melhora uma habilidade de cada vez. O objetivo é voltar porque existe algo novo para dominar — não porque és pressionado a voltar.</p><div class="p3b-next"><span style="font-size:10px;color:#D8CFC0">Próximo passo: um desafio curto.</span><button class="p3b-primary" id="p3bDailyButton" type="button">Desafio de hoje</button></div></div><div><div class="p3b-stats"><div class="p3b-stat"><strong id="p3bXp">0</strong><span>XP</span></div><div class="p3b-stat"><strong id="p3bPlays">0</strong><span>Rondas</span></div><div class="p3b-stat"><strong id="p3bBest">0</strong><span>Melhor</span></div></div><div class="p3b-return" id="p3bReturn"><strong>ANNAN:</strong> começa por uma experiência. O teu próximo resultado atualiza este painel.</div></div></div>\n      <div class="p3b-section-title"><h3>Perfil de habilidades</h3><p>estimativa de prática, não avaliação clínica</p></div><div class="p3b-skills" id="p3bSkills"></div>\n      <div class="p3b-section-title"><h3>Maestria</h3><p>5 etapas por experiência</p></div><div class="p3b-mastery-grid" id="p3bMastery"></div>\n      <div class="p3b-section-title"><h3>Desafio diário</h3><p>uma variação por dia</p></div><div class="p3b-daily" id="p3bDaily"><div class="p3b-daily-copy"><strong id="p3bDailyTitle">Desafio de hoje</strong><span id="p3bDailyText">Escolhe uma experiência e completa uma ronda.</span></div><span class="p3b-badge" id="p3bDailyBadge">ABERTO</span></div>`;\n    var anchor=hub.querySelector('.pch-phase3a');if(anchor&&anchor.parentNode)anchor.parentNode.insertBefore(section,anchor);else hub.insertBefore(section,hub.firstChild||null);\n\n    var skills=[['memory','Memória','🧠'],['focus','Foco','🎯'],['decision','Decisão','⚡'],['strategy','Estratégia','♟'],['finance','Finanças','💰']];\n    function render(){\n      document.getElementById('p3bXp').textContent=state.xp;document.getElementById('p3bPlays').textContent=state.plays;document.getElementById('p3bBest').textContent=state.bestScore;\n      var skillHost=document.getElementById('p3bSkills');skillHost.innerHTML=skills.map(function(x){var v=Math.round(state.skills[x[0]]);return '<button type="button" class="p3b-skill" aria-label="'+x[1]+' '+v+' por cento"><div class="p3b-skill-top"><span>'+x[2]+' '+x[1]+'</span><span>'+v+'%</span></div><div class="p3b-meter"><i style="width:'+v+'%"></i></div><small>'+ (v>=80?'forte':v>=45?'em evolução':'a desenvolver') +'</small></button>';}).join('');\n      var mh=document.getElementById('p3bMastery');mh.innerHTML=Object.keys(games).map(function(k){var g=games[k],m=state.masters[k]||0;return '<button type="button" class="p3b-mastery" data-p3b-game="'+k+'"><strong>'+g.icon+' '+g.label+'</strong><small>Maestria '+m+'/5</small><div class="p3b-dots">'+[0,1,2,3,4].map(function(i){return '<i class="'+(i<m?'on':'')+'"></i>';}).join('')+'</div></button>';}).join('');\n      var daily=document.getElementById('p3bDaily'),badge=document.getElementById('p3bDailyBadge');daily.classList.toggle('done',state.daily.completed);badge.textContent=state.daily.completed?'CONCLUÍDO':'ABERTO';document.getElementById('p3bDailyText').textContent=state.daily.completed?'Boa. Amanhã haverá uma nova variação.':'Completa uma ronda de qualquer experiência para concluir o desafio de hoje.';\n      var ret=document.getElementById('p3bReturn');if(!state.plays)ret.innerHTML='<strong>ANNAN:</strong> começa por uma experiência. O teu próximo resultado atualiza este painel.';else if(state.daily.completed)ret.innerHTML='<strong>ANNAN:</strong> desafio diário concluído. Volta quando quiseres superar a tua melhor marca.';else ret.innerHTML='<strong>ANNAN:</strong> já tens evolução registada. Falta apenas concluir o desafio de hoje.';\n    }\n    function launch(kind){var card=hub.querySelector('[data-p3a="'+kind+'"]');if(card){card.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(function(){card.click();},120);}}\n    document.getElementById('p3bDailyButton').addEventListener('click',function(){var keys=Object.keys(games),index=(today.split('-').join('').split('').reduce(function(a,b){return a+Number(b)},0))%keys.length;launch(keys[index]);});\n    document.getElementById('p3bMastery').addEventListener('click',function(e){var b=e.target.closest('[data-p3b-game]');if(b)launch(b.dataset.p3bGame);});\n    var observed=hub.querySelector('#annanPhase3aPanel');\n    if(observed&&window.MutationObserver){var last='';var observer=new MutationObserver(function(){var text=observed.textContent||'';if(!text||text===last)return;last=text;var success=/Acerto/i.test(text),attempt=/Tentativa registada/i.test(text);if(!success&&!attempt)return;var title=observed.querySelector('.pch-phase3a-result');if(!title)return;var currentKey=null;Object.keys(games).some(function(k){var c=hub.querySelector('[data-p3a="'+k+'"]');if(c&&c.classList.contains('active')){currentKey=k;return true;}return false;});if(!currentKey){var nm=(observed.querySelector('.pch-phase3a-title')||{}).textContent||'';currentKey=Object.keys(games).find(function(k){return nm.indexOf(games[k].label)>=0;})||null;}if(!currentKey)return;if(success&&title.dataset.p3bCounted==='1')return;if(title.dataset.p3bCounted==='1')return;title.dataset.p3bCounted='1';var g=games[currentKey],skill=g.skill;state.plays+=1;state.xp+=success?20:2;state.skills[skill]=Math.min(100,state.skills[skill]+(success?7:2));if(success)state.masters[currentKey]=Math.min(5,state.masters[currentKey]+1);state.bestScore=Math.max(state.bestScore,success?100:20);state.lastPlayedAt=new Date().toISOString();if(state.daily.date===today&&!state.daily.completed)state.daily.completed=true;save();render();});observer.observe(observed,{childList:true,subtree:true,characterData:true});}\n    render();\n  }\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();\n})();\n'''
script = script.replace(r'\n', '\n')
s += marker + script
p.write_text(s, encoding='utf-8')
print('OK: Fase 3B adicionada ao motor de experiência.')
